    "effectZh": "[登场时] \n以下选 1。\n•查看自己牌库上方的 3 张，将最多 1 张［特征：放课后 Climax Girls］公开并加入手牌。其余按任意顺序放回牌库下方。若成功加入手牌，可将自己手牌中的 1 张置入场外。\n•选择自己场上的其他［特征：放课后 Climax Girls］最多 1 枚，本回合中 BP+1000。",
